// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Size} from "../src/Size.sol";

contract InvMutTest is Test {
    Size c;
    function setUp() public { c = new Size(); }
    function testFuzz_property(bytes32 role, address account) public {
        // The contract is deployed but never initialized, so no role has ever been
        // granted to anyone: hasRole must report the (empty) stored membership,
        // which is false for every (role, account) pair. The mutant negates the
        // stored membership and returns true instead.
        assertTrue(!c.hasRole(role, account));
    }
}
